mapper.insert:
INSERT INTO wallet (
    user_id,
    currency_type,
    balance
) VALUES (
    #{userId},
    #{currencyType},
    #{balance}
)

INSERT IGNORE INTO wallet (
    user_id,
    currency_type,
    balance
) VALUES (
    #{userId},
    #{currencyType},
    #{balance}
)

mapper.update:
UPDATE wallet
SET balance = #{balance}
WHERE user_id = #{userId}
  AND currency_type = #{currencyType}

UPDATE wallet
SET balance = balance + #{amount}
WHERE user_id = #{userId}
  AND currency_type = #{currencyType}

UPDATE wallet
SET balance = balance - #{amount}
WHERE user_id = #{userId}
  AND currency_type = #{currencyType}
  AND balance >= #{amount}

mapper.select:
SELECT user_id AS userId, currency_type AS currencyType, balance, upt_date AS uptDate FROM wallet WHERE currency_type = #{currencyType}
AND user_id IN
#{id}

SELECT EXISTS(
    SELECT 1 FROM wallet
    WHERE user_id = #{userId}
      AND currency_type = #{currencyType}
)
